(async()=>{
      document.querySelector('[data-tab="native"]')?.click();
      const coverage=document.getElementById('native-component-coverage'); coverage.open=true;
      const imgs=[...document.querySelectorAll('#current-native-results img')];
      for(const img of imgs){img.closest('details').open=true;img.loading='eager';}
      await Promise.all(imgs.map(img=>img.decode()));
      const component=document.getElementById('native-component-filter'),runtime=document.getElementById('native-runtime-filter');
      component.value='claude-code';component.onchange();
      const claudeMatches=[...document.querySelectorAll('.native-run')].filter(x=>!x.hidden).length;
      runtime.value='Current Codex Desktop connection';runtime.onchange();
      const zeroMatched=!document.getElementById('native-filter-empty').hidden;
      document.querySelector('[data-native-jump]')?.click();
      const jumpCleared=component.value===''&&runtime.value==='';
      const img=imgs[0];img.closest('details').querySelector('button').id='verify-image-download';
      const txt=[...document.querySelectorAll('[data-native-download]')].find(x=>x.textContent==='Download codex-invocation.json');
      txt.closest('details').open=true;txt.id='verify-text-download';
      return JSON.stringify({title:document.title,coverageRows:document.querySelectorAll('[data-native-component-row]').length,
        imagesDecoded:imgs.filter(x=>x.naturalWidth>0).length,claudeMatches,zeroMatched,jumpCleared,
        nativeRuns:document.querySelectorAll('.native-run').length});})()

